import { validateSessionProposal } from '../intelligence/session-engine.js';
import {createM26Id} from '../platform/id.js';
export function createSessionDraft({clientId,title='Sesión IBERFIT',durationMinutes=50}={}){if(!clientId)throw new Error('M26_SESSION_CLIENT_REQUIRED');return {id:createM26Id(),clientId,title,durationMinutes,status:'draft',blocks:[],revision:0};}
export function addCatalogExercise(draft,exerciseId,catalog,prescription={}){const ex=catalog.get(exerciseId);if(!ex)throw new Error('M26_SESSION_EXERCISE_NOT_IN_CATALOG');if(draft.activeGroupId){const group=draft.blocks.find((b)=>b.id===draft.activeGroupId);if(!group)throw new Error('M26_SESSION_ACTIVE_GROUP_MISSING');if(!group.exerciseIds.includes(exerciseId))group.exerciseIds.push(exerciseId);const limit=group.type==='biserie'?2:group.type==='triserie'?3:null;if(limit&&group.exerciseIds.length>=limit)delete draft.activeGroupId;return draft;}draft.blocks.push({id:createM26Id(),type:'exercise',exerciseId,name:ex.name_es,sets:prescription.sets||3,reps:prescription.reps||'8–12',restSeconds:prescription.restSeconds||60,tempo:prescription.tempo||'controlado',targetRpe:prescription.targetRpe||7,targetRir:prescription.targetRir||3,alternativeId:prescription.alternativeId||null});return draft;}
export function addTrainingGroup(draft,type,exerciseIds=[]){if(!['biserie','triserie','circuito','amrap','tabata'].includes(type))throw new Error('M26_SESSION_GROUP_INVALID');const id=createM26Id();draft.blocks.push({id,type,exerciseIds:[...exerciseIds],rounds:type==='tabata'?8:3});draft.activeGroupId=id;return draft;}
export function closeTrainingGroup(draft){if(!draft.activeGroupId)return draft;const group=draft.blocks.find((b)=>b.id===draft.activeGroupId);if(!group?.exerciseIds?.length)throw new Error('M26_SESSION_GROUP_EMPTY');delete draft.activeGroupId;return draft;}
export function validateSessionDraft(draft,catalog){const errors=[];if(!draft.clientId)errors.push('clientId');if(!draft.blocks.length)errors.push('blocks');for(const b of draft.blocks){if(b.type==='exercise'){if(!catalog.has(b.exerciseId))errors.push(`exercise:${b.exerciseId}`);if(!b.sets||!b.reps||!b.restSeconds)errors.push(`prescription:${b.exerciseId}`);}else{const min=b.type==='biserie'?2:b.type==='triserie'?3:b.type==='circuito'?2:1;if((b.exerciseIds?.length||0)<min)errors.push(`group:${b.id}`);for(const id of b.exerciseIds||[])if(!catalog.has(id))errors.push(`exercise:${id}`);}}return {ok:errors.length===0,errors};}
export function buildPublishSessionCommand(draft,catalog,baseRevision=0){const check=validateSessionDraft(draft,catalog);if(!check.ok)throw new Error(`M26_SESSION_DRAFT_INVALID:${check.errors.join(',')}`);if(draft.previewAccepted!==true)throw new Error('M26_SESSION_PREVIEW_REQUIRED');return {type:'SESION_PUBLICAR',entityType:'session',entityId:draft.id,clientId:draft.clientId,baseRevision,previewAccepted:true,payload:{patch:structuredClone(draft)}};}
export function importAiProposalAsDraft(proposal,catalog){const check=validateSessionProposal(proposal,catalog);if(!check.ok)throw new Error(`M26_AI_PROPOSAL_INVALID:${check.errors.join(',')}`);const draft=createSessionDraft({clientId:proposal.clientId,durationMinutes:proposal.estimatedMinutes});for(const item of proposal.exercises)addCatalogExercise(draft,item.exerciseId,catalog,item);return draft;}
